/**
 * Open questions (Item 11): neutral questions generated by fixed rules from structural gaps in
 * the official record. Pure and deterministic; no network, no model, no opinion. Every rule has
 * one fixed template, so the wording is the same for every initiative; templates only fill in a
 * milestone number or a backer name. A question is a prompt to investigate, never a finding.
 */
import type { Claim, Initiative, Milestone, Organization, Pledge } from "@/lib/domain/schemas";
import { identityDomain, strictKey } from "@/lib/domain/identity";
import { SOURCE_LABELS, type SourceKind } from "@/lib/neutralLanguage";
import { stableId } from "@/lib/util/hash";
import { formatUsd } from "@/lib/util/money";
import { namesOverlap, possibleSelfPledge, recipientNames } from "./self-pledge";

export const OPEN_QUESTIONS_VERSION = "open-questions@1";

export const OPEN_QUESTION_NOTICE = "A question is not an accusation and not a finding that something is wrong.";

/** Display order of the categories. */
export const OPEN_QUESTION_CATEGORIES = ["Timeline", "Delivery", "Funding", "Adoption", "Evidence"] as const;
export type OpenQuestionCategory = (typeof OPEN_QUESTION_CATEGORIES)[number];

export const OPEN_QUESTION_RULES = [
  { id: "milestone_no_target_date", n: 1, category: "Timeline", label: "Milestone without a target date", field: "milestones[].targetMonth", template: "Is there a target date for milestone {n}?" },
  { id: "rfp_no_recipient", n: 2, category: "Delivery", label: "RFP without a recipient team", field: "recipientTeam", template: "Who is expected to deliver?" },
  { id: "no_repository_or_product_link", n: 3, category: "Evidence", label: "No repository or product link", field: "links, textLinks", template: "Is there a public repository or product link for this work?" },
  { id: "adoption_named_party", n: 4, category: "Adoption", label: "Adoption milestone that names a third party", field: "milestones[].adoption, milestones[].criteria", template: "Has any party named in milestone {n} confirmed the adoption it describes?" },
  { id: "possible_self_pledge", n: 5, category: "Funding", label: "Backer name overlaps the recipient team", field: "pledges[].company, recipientTeam", template: "Can the team confirm whether the pledge from {company} is a self-pledge? (possible self-pledge, unverified)" },
  { id: "pledge_not_received", n: 6, category: "Funding", label: "Pledged, not yet received", field: "pledges[].status", template: "Is there an expected date for the pledged amount from {company} to be received?" },
  { id: "no_milestone_reviewer", n: 7, category: "Delivery", label: "No named milestone reviewer", field: "milestoneReviewer", template: "Who will review the milestones?" },
  { id: "existing_claim_without_link", n: 8, category: "Evidence", label: "Statement about existing functionality without a link", field: "claims (kind integration, status applicant_reported)", template: "Is there a public link that shows the quoted statement?" },
] as const satisfies readonly { id: string; n: number; category: OpenQuestionCategory; label: string; field: string; template: string }[];

export type OpenQuestionRule = (typeof OPEN_QUESTION_RULES)[number];
export type OpenQuestionRuleId = OpenQuestionRule["id"];
const RULE = Object.fromEntries(OPEN_QUESTION_RULES.map((r) => [r.id, r])) as Record<OpenQuestionRuleId, OpenQuestionRule>;

export interface OpenQuestion {
  /** Stable across republishing: rule, initiative and the record the rule looked at. */
  id: string;
  initiativeId: string;
  ruleId: OpenQuestionRuleId;
  ruleNumber: number;
  ruleLabel: string;
  category: OpenQuestionCategory;
  question: string;
  /** The official field the rule read. */
  field: string;
  /** What the field holds, in plain words (e.g. "Not recorded"). */
  value: string;
  /** Verbatim text from the record, shown as a quotation, or null. */
  quotes: string[];
  quoteKind: Extract<SourceKind, "official" | "applicant"> | null;
  sourceKind: SourceKind;
  sourceLabel: string;
  sourceName: string;
  sourceUrl: string;
  /** Extra facts (named parties, amounts, links found). */
  details: string[];
  /** Sort key inside a rule (milestone index, pledge or claim order). */
  order: number;
  /** Id of the milestone, pledge or claim the rule looked at; null for initiative-level fields. */
  ref: string | null;
}

export interface OpenQuestionInput {
  initiative: Initiative;
  organization: Pick<Organization, "name" | "names" | "website"> | null;
  milestones: Milestone[];
  pledges: Pledge[];
  claims: Claim[];
  /** Party names found in enumerated lists across the cohort's adoption milestones (see cohortPartyLexicon). */
  lexicon?: readonly string[];
}

const fill = (template: string, vars: Record<string, string | number>) => template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));

function make(ruleId: OpenQuestionRuleId, ini: Initiative, key: string, order: number, vars: Record<string, string | number>, rest: Omit<OpenQuestion, "id" | "initiativeId" | "ruleId" | "ruleNumber" | "ruleLabel" | "category" | "question" | "field" | "order" | "sourceLabel" | "ref"> & { field?: string; ref?: string }): OpenQuestion {
  const r = RULE[ruleId];
  return {
    id: stableId("oq", r.id, ini.id, key),
    initiativeId: ini.id,
    ruleId: r.id,
    ruleNumber: r.n,
    ruleLabel: r.label,
    category: r.category,
    question: fill(r.template, vars),
    field: rest.field ?? r.field,
    order,
    ...rest,
    ref: rest.ref ?? null,
    sourceLabel: SOURCE_LABELS[rest.sourceKind],
  };
}

const official = (ini: Initiative) => ({ sourceKind: "official" as const, sourceName: "Official initiative record", sourceUrl: ini.url });

// ───────────────────────────── Rule 1: milestone without a target date ─────────────────────────────

/** Open milestones whose official targetMonth is empty. Completed milestones are left out. */
export function ruleMilestoneNoTargetDate(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  return x.milestones
    .filter((m) => !m.done && !m.targetMonth)
    .map((m) =>
      make("milestone_no_target_date", ini, String(m.index), m.index, { n: m.index + 1 }, {
        field: `milestones[${m.index}].targetMonth`,
        ref: m.id,
        value: "Not recorded",
        quotes: [m.name],
        quoteKind: "official",
        ...official(ini),
        sourceName: "Official milestone record",
        details: [`Milestone ${m.index + 1}: ${formatUsd(m.amountCents)}`],
      }),
    );
}

// ───────────────────────────── Rule 2: RFP without a recipient team ─────────────────────────────

export function ruleRfpNoRecipient(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  if (ini.type !== "rfp" || ini.recipientTeam?.trim()) return [];
  return [make("rfp_no_recipient", ini, "", 0, {}, { value: "Not recorded (request for proposals)", quotes: [], quoteKind: null, ...official(ini), details: [] })];
}

// ───────────────────────────── Rule 3: no repository or product link ─────────────────────────────

const REPO_HOSTS = new Set(["github.com", "gitlab.com", "codeberg.org", "bitbucket.org"]);
/** Words in recipient names that are too generic to identify a domain. */
const GENERIC_NAME_WORDS = new Set(["team", "labs", "lab", "network", "grant", "association", "cooperative", "collective", "foundation", "security", "inc", "ltd", "llc", "the", "and"]);

/** A link to a code repository: GitHub, GitLab, Codeberg or Bitbucket with an owner and a repository in the path. */
export function isRepositoryLink(url: string): boolean {
  try {
    const u = new URL(url);
    if (!REPO_HOSTS.has(u.hostname.toLowerCase().replace(/^www\./, ""))) return false;
    return u.pathname.split("/").filter(Boolean).length >= 2;
  } catch {
    return false;
  }
}

/**
 * A product link: a link on the recipient's own domain. That is the domain of the official
 * recipient URL or the organization's website, or a domain whose name equals the recipient
 * name or one of its distinctive words ("owney.app" for Owney).
 */
export function isProductLink(url: string, ini: Pick<Initiative, "recipientUrl" | "recipientTeam">, org: Pick<Organization, "name" | "names" | "website"> | null): boolean {
  const dom = identityDomain(url);
  if (!dom || !/^https?:\/\//i.test(url) || dom.includes("/")) return false;
  const own = new Set([identityDomain(ini.recipientUrl), identityDomain(org?.website)].filter((d): d is string => !!d && !d.includes("/")));
  if (own.has(dom)) return true;
  const label = dom.split(".")[0] ?? "";
  if (label.length < 4) return false;
  const names = recipientNames({ recipientTeam: ini.recipientTeam, organization: org ? { name: org.name, names: org.names } : null });
  const keys = new Set<string>();
  for (const n of names) {
    keys.add(strictKey(n));
    for (const w of n.split(/[^A-Za-z0-9]+/)) if (w.length >= 4 && !GENERIC_NAME_WORDS.has(w.toLowerCase())) keys.add(strictKey(w));
  }
  return keys.has(label);
}

export function ruleNoRepositoryOrProductLink(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  const urls = [...new Set([...ini.links, ...ini.textLinks.map((t) => t.url)])];
  if (urls.some((u) => isRepositoryLink(u) || isProductLink(u, ini, x.organization))) return [];
  const hosts = [...new Set(urls.map((u) => identityDomain(u)).filter((h): h is string => !!h))].sort();
  return [
    make("no_repository_or_product_link", ini, "", 0, {}, {
      value: urls.length ? `${urls.length} ${urls.length === 1 ? "link" : "links"} found; none is a code repository or on the recipient's own domain` : "No links in the official record or the proposal text",
      quotes: [],
      quoteKind: null,
      ...official(ini),
      details: hosts.length ? [`Linked domains: ${hosts.join(", ")}`] : [],
    }),
  ];
}

// ───────────────────────────── Rule 4: adoption milestone naming a third party ─────────────────────────────

/** Capitalized words that name a place, chain family or concept, never a party. */
export const NOT_A_PARTY = ["Ethereum", "Ethereum L2", "Ethereum L2s", "Ethereum mainnet", "L1", "L2", "L2s", "L2BEAT", "ETH", "DeFi", "AI", "CEX", "TVL", "EIP", "ERC", "CI", "CI/CD", "Linux", "GitHub", "API", "SDK", "MCP", "SKILL", "CAR", "TEE", "ZK", "RPC", "UI", "IDE", "Enterprise", "USD"];
const NOT_A_PARTY_SET = new Set(NOT_A_PARTY);
const MONTHS = /^(January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec|Q[1-4])$/;

/**
 * Single words that are also ordinary English or product nouns ("a mainnet Safe", "Safe Harbor",
 * "Base" at the start of a sentence). They count only inside an enumerated list of names.
 */
export const LIST_ONLY_NAMES = ["Safe", "Base", "Ink", "Sky", "Curve", "Lighter", "Keeper", "Rainbow", "Phantom", "Foundry", "Remix", "Medusa", "Compound", "Across", "Synapse", "Delay", "Roles", "Seer", "Walnut", "Everything", "Unlink"];
const LIST_ONLY = new Set(LIST_ONLY_NAMES);

/** Words that mark the names after them as excluded parties ("outside Blobscan", "independent of"). */
const EXCLUSION = /\b(outside|excluding|exclude|independent of|other than|beyond|none of them|not counting|unaffiliated with)\s+(the\s+)?$/i;

const NAME_WORD = /^(?:[A-Z0-9][A-Za-z0-9.'’&/-]*|[a-z]+[A-Z0-9][A-Za-z0-9.'’&/-]*)$/;
const isNameWord = (w: string) => NAME_WORD.test(w);

/** True when every word is name-like ("Trail of Bits" allows "of"). */
function isName(item: string): boolean {
  const words = item.split(/\s+/).filter(Boolean);
  if (words.length === 0 || words.length > 4) return false;
  if (!isNameWord(words[0]!) || !isNameWord(words[words.length - 1]!)) return false;
  if (!words.every((w) => isNameWord(w) || w === "of")) return false;
  // A name starts with a letter or with digits followed by letters ("1inch"); numbers, amounts and dates are not names.
  if (!/^[0-9]*[A-Za-z]/.test(words[0]!) || MONTHS.test(words[0]!) || (item.match(/[A-Za-z]/g) ?? []).length < 2) return false;
  return !NOT_A_PARTY_SET.has(item);
}

/** Trailing name words of a phrase ("1 of them from the Robinhood Chain" gives "Robinhood Chain"). */
function trailingName(item: string): { name: string; before: string } | null {
  const words = item.split(/\s+/).filter(Boolean);
  let i = words.length;
  while (i > 0 && isNameWord(words[i - 1]!)) i--;
  const name = words.slice(i).join(" ");
  return name && isName(name) ? { name, before: words.slice(0, i).join(" ") } : null;
}

/** Leading name words of a phrase ("Mantle teams" gives "Mantle"). */
function leadingName(item: string): string | null {
  const words = item.split(/\s+/).filter(Boolean);
  let i = 0;
  while (i < words.length && isNameWord(words[i]!)) i++;
  const name = words.slice(0, i).join(" ");
  return name && isName(name) ? name : null;
}

/**
 * Names in enumerated lists such as "from this list: MetaMask, Rabby, Trust Wallet" or "(Tenderly,
 * Foundry, Hardhat)". A list is two or more consecutive comma, "or" or "and" separated items in one
 * clause; at least one item is a complete name, the first may end in a name and the last may start
 * with one. Lists introduced by an exclusion ("outside A, B and C") are dropped.
 */
export function listedNames(text: string): string[] {
  const segments: string[] = [];
  const main = text.replace(/\(([^()]*)\)/g, (_, inner: string) => {
    segments.push(inner);
    return "";
  });
  segments.unshift(main);
  const out: string[] = [];
  for (const seg of segments) {
    for (const clause of seg.split(/[:;|]|\.(?:\s|$)|\s[-–]\s/)) {
      const items = clause
        .split(/,\s*|\s+or\s+|\s+and\s+/)
        .map((s) => s.trim().replace(/^(?:or|and)\s+/, ""))
        .filter(Boolean);
      let i = 0;
      while (i < items.length) {
        const run: { name: string; full: boolean; excluded: boolean }[] = [];
        let j = i;
        const first = items[j]!;
        if (isName(first)) {
          run.push({ name: first, full: true, excluded: false });
          j++;
        } else {
          const t = trailingName(first);
          if (t && j + 1 < items.length && isName(items[j + 1]!)) {
            run.push({ name: t.name, full: false, excluded: EXCLUSION.test(`${t.before} `) });
            j++;
          }
        }
        while (j < items.length && run.length > 0 && isName(items[j]!)) run.push({ name: items[j++]!, full: true, excluded: false });
        if (run.length > 0 && j < items.length) {
          const l = leadingName(items[j]!);
          if (l) run.push({ name: l, full: false, excluded: false });
        }
        if (run.length >= 2 && run.some((r) => r.full) && !run[0]!.excluded) out.push(...run.map((r) => r.name));
        i = Math.max(j, i + 1);
      }
    }
  }
  return [...new Set(out)];
}

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/** Occurrences of a known name outside an exclusion context, case-sensitive with word boundaries. */
function standaloneMention(text: string, name: string): boolean {
  const re = new RegExp(`(?<![A-Za-z0-9])${escapeRe(name)}(?![A-Za-z0-9])`, "g");
  for (const m of text.matchAll(re)) if (!EXCLUSION.test(text.slice(Math.max(0, m.index - 30), m.index))) return true;
  return false;
}

/**
 * Party names known from the cohort: every name found in an enumerated list in any adoption
 * milestone, plus organization names in the dataset that cannot be ordinary words (several words,
 * an inner capital, a digit or a dot, or all capitals).
 */
export function cohortPartyLexicon(milestones: readonly Milestone[], organizations: readonly Pick<Organization, "names" | "anonymous">[]): string[] {
  const names = new Set<string>();
  for (const m of milestones) if (m.adoption) for (const c of m.criteria) for (const n of listedNames(c)) names.add(n);
  for (const o of organizations) {
    if (o.anonymous) continue;
    for (const n of o.names) {
      const t = n.trim();
      if (t.length < 3 || /[(),]/.test(t)) continue;
      if (/\s/.test(t) || /[a-z][A-Z]/.test(t) || /[0-9.]/.test(t) || /^[A-Z]{3,}$/.test(t)) names.add(t);
    }
  }
  return [...names].filter((n) => !NOT_A_PARTY_SET.has(n)).sort();
}

/** True when a party name and one of the recipient names contain each other as whole words. */
function isRecipient(name: string, recipients: string[]): boolean {
  return namesOverlap(name, recipients) !== null || recipients.some((r) => namesOverlap(r, [name]) !== null);
}

/** Third parties named in one adoption milestone, in order of first appearance, with the criteria that name them. */
export function namedParties(m: Pick<Milestone, "criteria">, recipients: string[], lexicon: readonly string[] = []): { parties: string[]; criteria: string[] } {
  const parties: string[] = [];
  const criteria: string[] = [];
  for (const c of m.criteria) {
    const found = new Set<string>(listedNames(c));
    for (const n of lexicon) if (!LIST_ONLY.has(n) && !found.has(n) && standaloneMention(c, n)) found.add(n);
    const keep = [...found].filter((n) => !isRecipient(n, recipients));
    // Drop a name that is part of a longer name found in the same criterion ("Coinbase" in "Coinbase Wallet").
    const distinct = keep.filter((n) => !keep.some((o) => o !== n && new RegExp(`(?<![A-Za-z0-9])${escapeRe(n)}(?![A-Za-z0-9])`).test(o)));
    if (distinct.length === 0) continue;
    criteria.push(c);
    const pos = (n: string) => c.indexOf(n);
    for (const n of distinct.sort((a, b) => pos(a) - pos(b) || a.localeCompare(b))) if (!parties.includes(n)) parties.push(n);
  }
  return { parties, criteria };
}

export function ruleAdoptionNamedParty(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  const recipients = recipientNames({ recipientTeam: ini.recipientTeam, organization: x.organization ? { name: x.organization.name, names: x.organization.names } : null });
  const out: OpenQuestion[] = [];
  for (const m of x.milestones) {
    if (!m.adoption || m.done) continue;
    const { parties, criteria } = namedParties(m, recipients, x.lexicon ?? []);
    if (parties.length === 0) continue;
    out.push(
      make("adoption_named_party", ini, String(m.index), m.index, { n: m.index + 1 }, {
        field: `milestones[${m.index}].criteria`,
        ref: m.id,
        value: `Adoption milestone (adoption = true): ${m.name}`,
        quotes: criteria,
        quoteKind: "official",
        ...official(ini),
        sourceName: "Official milestone record",
        details: [`Named in the criteria: ${parties.join(", ")}`],
      }),
    );
  }
  return out;
}

// ───────────────────────────── Rules 5 and 6: pledges ─────────────────────────────

const byPledgeOrder = (a: Pledge, b: Pledge) => a.company.localeCompare(b.company, "en") || (a.createdAt ?? "").localeCompare(b.createdAt ?? "") || (a.id < b.id ? -1 : 1);

function pledgeSource(p: Pledge, ini: Initiative) {
  return { sourceKind: "official" as const, sourceName: "Official pledge record", sourceUrl: p.provenance.sourceUrls[0] ?? ini.url };
}

/** Uses the same conservative, whole-word name check as the evidence card (lib/intelligence/self-pledge.ts). */
export function rulePossibleSelfPledge(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  const subject = { recipientTeam: ini.recipientTeam, organization: x.organization ? { name: x.organization.name, names: x.organization.names } : null };
  return [...x.pledges].sort(byPledgeOrder).flatMap((p, i) => {
    const sp = possibleSelfPledge(p.company, subject);
    if (!sp.flagged) return [];
    return [
      make("possible_self_pledge", ini, p.id, i, { company: p.company }, {
        value: `Backer “${p.company}”, recipient name “${sp.matchedName}”`,
        ref: p.id,
        quotes: [],
        quoteKind: null,
        ...pledgeSource(p, ini),
        details: [`${formatUsd(p.amountCents)} ${p.status === "received" ? "received" : "pledged"}`, "Name overlap only; not verified"],
      }),
    ];
  });
}

export function rulePledgeNotReceived(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  return [...x.pledges]
    .sort(byPledgeOrder)
    .filter((p) => p.status === "pledged")
    .map((p, i) =>
      make("pledge_not_received", ini, p.id, i, { company: p.company }, {
        field: "pledges[].status",
        value: `pledged (${formatUsd(p.amountCents)}), not marked received`,
        ref: p.id,
        quotes: [],
        quoteKind: null,
        ...pledgeSource(p, ini),
        details: p.createdAt ? [`Pledge recorded ${p.createdAt.slice(0, 10)}`] : [],
      }),
    );
}

// ───────────────────────────── Rule 7: no named milestone reviewer ─────────────────────────────

export function ruleNoMilestoneReviewer(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  if (ini.milestoneReviewer?.trim()) return [];
  return [make("no_milestone_reviewer", ini, "", 0, {}, { value: "Not recorded", quotes: [], quoteKind: null, ...official(ini), details: [] })];
}

// ───────────────────────────── Rule 8: existing functionality without a link ─────────────────────────────

const pageKey = (u: string) => u.replace(/#.*$/, "").replace(/\/+$/, "");

/** Proposal sections that describe what exists today. Scope and commitments describe planned work. */
export const EXISTING_WORK_SECTIONS = ["why", "why_grant", "team", "existing", "details"];
/**
 * A link written as plain text with a path ("github.com/org/repo") counts as a link. A bare
 * domain used as a company name ("beel.com") does not point to a page that shows anything.
 */
const BARE_LINK = /(?:https?:\/\/|www\.)\S+|\b[a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)*\.[a-z]{2,6}\/[^\s)]+/i;

/**
 * Statements the claims pipeline classified as existing integrations or production use (kind
 * "integration", status "applicant_reported", which excludes planned work) in a section that
 * describes existing work, whose sentence links nothing besides the proposal itself (no URL and
 * no link written as text) and which have no supporting evidence.
 */
export function ruleExistingClaimWithoutLink(x: OpenQuestionInput): OpenQuestion[] {
  const ini = x.initiative;
  const self = pageKey(ini.url);
  return x.claims
    .filter(
      (c) =>
        c.kind === "integration" &&
        c.status === "applicant_reported" &&
        !!c.section &&
        EXISTING_WORK_SECTIONS.includes(c.section) &&
        c.supportingEvidenceIds.length === 0 &&
        c.sourceUrls.every((u) => pageKey(u) === self) &&
        !BARE_LINK.test(c.quote ?? c.assertion),
    )
    .sort((a, b) => (a.section ?? "").localeCompare(b.section ?? "") || (a.id < b.id ? -1 : 1))
    .map((c, i) =>
      make("existing_claim_without_link", ini, c.id, i, {}, {
        field: `claims[${c.id}]`,
        ref: c.id,
        value: "No link in the sentence and no supporting evidence",
        quotes: [c.quote ?? c.assertion],
        quoteKind: "applicant",
        sourceKind: "applicant",
        sourceName: "Official proposal",
        sourceUrl: c.section ? `${ini.url}#${c.section}` : ini.url,
        details: [],
      }),
    );
}

export const RULE_FUNCTIONS: Record<OpenQuestionRuleId, (x: OpenQuestionInput) => OpenQuestion[]> = {
  milestone_no_target_date: ruleMilestoneNoTargetDate,
  rfp_no_recipient: ruleRfpNoRecipient,
  no_repository_or_product_link: ruleNoRepositoryOrProductLink,
  adoption_named_party: ruleAdoptionNamedParty,
  possible_self_pledge: rulePossibleSelfPledge,
  pledge_not_received: rulePledgeNotReceived,
  no_milestone_reviewer: ruleNoMilestoneReviewer,
  existing_claim_without_link: ruleExistingClaimWithoutLink,
};

const catIndex = (c: OpenQuestionCategory) => OPEN_QUESTION_CATEGORIES.indexOf(c);

/** All open questions for one initiative, ordered by category, rule number, then the record order. */
export function openQuestions(x: OpenQuestionInput): OpenQuestion[] {
  const all = OPEN_QUESTION_RULES.flatMap((r) => RULE_FUNCTIONS[r.id](x));
  return all.sort((a, b) => catIndex(a.category) - catIndex(b.category) || a.ruleNumber - b.ruleNumber || a.order - b.order || (a.id < b.id ? -1 : 1));
}

export type CategoryCounts = Record<OpenQuestionCategory, number>;

export function countByCategory(qs: readonly OpenQuestion[]): CategoryCounts {
  const out = Object.fromEntries(OPEN_QUESTION_CATEGORIES.map((c) => [c, 0])) as CategoryCounts;
  for (const q of qs) out[q.category]++;
  return out;
}

/** Plain-text list for "Copy as list": one numbered line per question with its category and source link. */
export function questionsAsText(title: string, qs: readonly Pick<OpenQuestion, "question" | "category" | "sourceUrl">[]): string {
  const lines = [`Open questions: ${title}`, OPEN_QUESTION_NOTICE, ""];
  qs.forEach((q, i) => lines.push(`${i + 1}. ${q.question} (${q.category}; source: ${q.sourceUrl})`));
  return lines.join("\n");
}
